'use strict';

/**
 * Sliding window rate limiter middleware for Express.
 *
 * This is a TRUE sliding window: every request timestamp is stored per client,
 * and on each incoming request all timestamps older than `windowMs` are evicted
 * before the count is evaluated. There is no fixed interval that resets the
 * counter, so a client cannot burst 2x maxRequests across a window boundary
 * (the classic fixed-window flaw).
 *
 * NOTE ON `req.ip` AND PROXIES:
 *   `req.ip` reflects the socket's remote address unless Express is configured
 *   to trust proxies. Behind a reverse proxy / load balancer (nginx, ELB,
 *   Cloudflare, Heroku, ...) every request appears to come from the proxy's IP,
 *   so a single shared bucket would rate limit all of your users together.
 *   Enable trust proxy so Express derives `req.ip` from `X-Forwarded-For`:
 *
 *       app.set('trust proxy', 1);          // trust the first proxy hop
 *       app.set('trust proxy', 'loopback'); // or a subnet / predicate
 *
 *   Only trust proxy when you actually run behind one you control: clients can
 *   forge `X-Forwarded-For`, so trusting it on a directly exposed server lets an
 *   attacker rotate the header and bypass the limiter entirely. If you need a
 *   different identity (API key, user id), pass a custom `keyGenerator`.
 */

const DEFAULT_WINDOW_MS = 60 * 1000;
const DEFAULT_MAX_REQUESTS = 100;
const CLEANUP_INTERVAL_MS = 60 * 1000;

function createRateLimiter(options = {}) {
  const {
    windowMs = DEFAULT_WINDOW_MS,
    maxRequests = DEFAULT_MAX_REQUESTS,
    keyGenerator = (req) => req.ip,
    cleanupIntervalMs = CLEANUP_INTERVAL_MS,
  } = options;

  if (!Number.isFinite(windowMs) || windowMs <= 0) {
    throw new TypeError('windowMs must be a positive number');
  }
  if (!Number.isInteger(maxRequests) || maxRequests < 0) {
    throw new TypeError('maxRequests must be a non-negative integer');
  }

  /** @type {Map<string, number[]>} key -> ascending list of request timestamps */
  const hits = new Map();

  /**
   * Drop every timestamp that fell out of the window. Timestamps are appended
   * in ascending order, so the expired ones are always a prefix of the array
   * and one splice is enough.
   */
  function prune(timestamps, cutoff) {
    let i = 0;
    while (i < timestamps.length && timestamps[i] <= cutoff) i++;
    if (i > 0) timestamps.splice(0, i);
    return timestamps;
  }

  function middleware(req, res, next) {
    const now = Date.now();
    const cutoff = now - windowMs;

    // A missing key (e.g. no socket address) would merge unrelated clients into
    // one bucket, so fall back to a stable placeholder rather than `undefined`.
    const key = keyGenerator(req);
    const bucketKey = key == null ? 'unknown' : String(key);

    let timestamps = hits.get(bucketKey);
    if (timestamps === undefined) {
      timestamps = [];
      hits.set(bucketKey, timestamps);
    }

    prune(timestamps, cutoff);

    if (timestamps.length >= maxRequests) {
      // The oldest surviving timestamp is the first to expire, which is exactly
      // when a slot frees up. (Guard for maxRequests === 0: no timestamps.)
      const resetMs = timestamps.length > 0
        ? timestamps[0] + windowMs
        : now + windowMs;
      const retryAfterSec = Math.max(1, Math.ceil((resetMs - now) / 1000));

      res.setHeader('X-RateLimit-Limit', maxRequests);
      res.setHeader('X-RateLimit-Remaining', 0);
      res.setHeader('X-RateLimit-Reset', Math.ceil(resetMs / 1000));
      res.setHeader('Retry-After', retryAfterSec);

      res.status(429).json({
        error: 'Rate limit exceeded',
        retryAfter: retryAfterSec,
      });
      return; // deliberately do NOT call next()
    }

    timestamps.push(now);

    const remaining = Math.max(0, maxRequests - timestamps.length);
    // With a sliding window the "reset" is when the oldest hit expires; if this
    // was the only hit, that is one full window from now.
    const resetMs = timestamps[0] + windowMs;

    res.setHeader('X-RateLimit-Limit', maxRequests);
    res.setHeader('X-RateLimit-Remaining', remaining);
    res.setHeader('X-RateLimit-Reset', Math.ceil(resetMs / 1000));

    next();
  }

  // Requests stop arriving for an IP but its entry would live forever, so sweep
  // buckets whose timestamps have all aged out of the window.
  const cleanupTimer = setInterval(() => {
    const cutoff = Date.now() - windowMs;
    for (const [key, timestamps] of hits) {
      prune(timestamps, cutoff);
      if (timestamps.length === 0) hits.delete(key);
    }
  }, cleanupIntervalMs);

  // Without unref() the interval alone keeps the event loop alive, so a script
  // that finished its work would never exit.
  if (typeof cleanupTimer.unref === 'function') cleanupTimer.unref();

  /** Stop the cleanup timer and release all tracked state. */
  middleware.close = function close() {
    clearInterval(cleanupTimer);
    hits.clear();
  };

  /** Forget one client (useful in tests, or after a successful login). */
  middleware.reset = function reset(key) {
    if (key === undefined) hits.clear();
    else hits.delete(String(key));
  };

  return middleware;
}

module.exports = createRateLimiter;
module.exports.createRateLimiter = createRateLimiter;
```

## Usage

```js
const express = require('express');
const { createRateLimiter } = require('./rateLimiter');

const app = express();

// Behind a reverse proxy this is REQUIRED for req.ip to be the real client IP.
// app.set('trust proxy', 1);

const limiter = createRateLimiter({
  windowMs: 60 * 1000, // 1 minute
  maxRequests: 100,
});

app.use(limiter);              // globally
// app.use('/api', limiter);   // or just one subtree

app.get('/', (req, res) => res.json({ ok: true }));

const server = app.listen(3000, () => console.log('listening on :3000'));

process.on('SIGTERM', () => {
  limiter.close();   // clears the cleanup interval
  server.close();
});
```

## Notes on the implementation

- **Why it's genuinely sliding:** the decision is made from `timestamps.filter(t > now - windowMs).length`, recomputed per request. There is no counter that a scheduled tick zeroes out, so the limit holds over *every* rolling `windowMs` interval, not just aligned ones.
- **Pruning is O(expired), not O(n):** since timestamps are pushed in ascending order, expired entries form a prefix, so a single `splice(0, i)` removes them.
- **`X-RateLimit-Reset` is the oldest hit's expiry**, which is when the next slot actually frees up — the meaningful value for a sliding window (a fixed-window limiter would report the next boundary).
- **`unref()` plus `close()`:** `close()` is the explicit teardown you asked for; `unref()` is belt-and-braces so a forgotten limiter can't hang a short-lived process.
- **Scope:** state is per-process. Across multiple workers/instances each has its own view, so the effective limit is `maxRequests × instances` — use Redis (e.g. sorted sets with `ZREMRANGEBYSCORE`, same algorithm) if you need a shared limit.

