```javascript
/**
 * sliding-window-rate-limiter.js
 *
 * A TRUE sliding-window rate limiter for Express.
 *
 * Unlike a "fixed window" limiter (which resets a counter every N ms and lets
 * up to 2x maxRequests through near a window boundary — e.g. maxRequests at
 * 0:59 and another maxRequests at 1:01), this implementation keeps the actual
 * request timestamps for each client and only counts the ones that fall
 * within the last `windowMs` milliseconds, relative to *now* on every request.
 * The window "slides" continuously instead of snapping back to zero.
 *
 * NOTE on req.ip / trust proxy:
 *   Express derives `req.ip` from the socket's remote address unless you set
 *   `app.set('trust proxy', ...)`, in which case it reads the left-most entry
 *   of the `X-Forwarded-For` header (or whatever your trust proxy config
 *   specifies). If this app sits behind a reverse proxy / load balancer
 *   (nginx, ALB, Heroku, Cloudflare, etc.) and you do NOT set `trust proxy`,
 *   every request will appear to come from the proxy's IP and all clients
 *   will share a single rate-limit bucket. Conversely, if you blindly trust
 *   `X-Forwarded-For` without configuring `trust proxy` to the correct number
 *   of hops (or a specific list of trusted proxy IPs), clients can spoof the
 *   header and evade rate limiting entirely. Always set
 *   `app.set('trust proxy', <correct value>)` to match your actual network
 *   topology before relying on `req.ip` for rate limiting.
 */

'use strict';

/**
 * @param {Object} [options]
 * @param {number} [options.windowMs=60000]   Sliding window size in ms.
 * @param {number} [options.maxRequests=100]  Max requests allowed per window.
 * @param {function(import('express').Request): string} [options.keyGenerator]
 *        Function to derive the client key from the request. Defaults to `req.ip`.
 * @returns {function & { close: function }} Express middleware with a `close()` method.
 */
function createRateLimiter(options = {}) {
  const windowMs = options.windowMs ?? 60000;
  const maxRequests = options.maxRequests ?? 100;
  const keyGenerator = options.keyGenerator ?? ((req) => req.ip);

  // Map<clientKey, number[]> — sorted ascending array of request timestamps (ms epoch)
  const store = new Map();

  function pruneOld(timestamps, now) {
    const cutoff = now - windowMs;
    // Timestamps are appended in increasing order, so we can binary-search
    // (or just linear-scan from the front) for the first index still in window.
    let start = 0;
    while (start < timestamps.length && timestamps[start] <= cutoff) {
      start++;
    }
    return start === 0 ? timestamps : timestamps.slice(start);
  }

  function middleware(req, res, next) {
    const now = Date.now();
    const key = keyGenerator(req);

    let timestamps = store.get(key) || [];
    timestamps = pruneOld(timestamps, now);

    if (timestamps.length >= maxRequests) {
      // Rejected: the request that will "free up" a slot is the oldest one
      // still in the window; retryAfter is how long until it ages out.
      store.set(key, timestamps); // keep pruned array persisted
      const oldest = timestamps[0];
      const retryAfterMs = Math.max(0, oldest + windowMs - now);
      const retryAfterSec = Math.ceil(retryAfterMs / 1000);

      res.setHeader('Retry-After', String(retryAfterSec));
      res.setHeader('X-RateLimit-Limit', String(maxRequests));
      res.setHeader('X-RateLimit-Remaining', '0');
      res.setHeader('X-RateLimit-Reset', String(Math.ceil((oldest + windowMs) / 1000)));

      return res.status(429).json({
        error: 'Rate limit exceeded',
        retryAfter: retryAfterSec,
      });
    }

    // Allowed: record this request's timestamp.
    timestamps.push(now);
    store.set(key, timestamps);

    const remaining = Math.max(0, maxRequests - timestamps.length);
    // Reset = when the oldest recorded request will fall out of the window
    // (i.e. when the count could next decrease). With only this request,
    // that's just windowMs from now.
    const resetAt = Math.ceil((timestamps[0] + windowMs) / 1000);

    res.setHeader('X-RateLimit-Limit', String(maxRequests));
    res.setHeader('X-RateLimit-Remaining', String(remaining));
    res.setHeader('X-RateLimit-Reset', String(resetAt));

    next();
  }

  // Periodic cleanup: drop entries for keys with no requests in the last
  // windowMs, so the store doesn't grow unbounded with stale/one-off IPs.
  const cleanupInterval = setInterval(() => {
    const now = Date.now();
    for (const [key, timestamps] of store.entries()) {
      const pruned = pruneOld(timestamps, now);
      if (pruned.length === 0) {
        store.delete(key);
      } else if (pruned.length !== timestamps.length) {
        store.set(key, pruned);
      }
    }
  }, 60000);

  // Don't let the cleanup timer keep the Node process alive on its own.
  if (typeof cleanupInterval.unref === 'function') {
    cleanupInterval.unref();
  }

  middleware.close = function close() {
    clearInterval(cleanupInterval);
    store.clear();
  };

  // Expose the store for testing/inspection purposes (optional, non-essential).
  middleware._store = store;

  return middleware;
}

module.exports = { createRateLimiter };
```

Usage example:

```javascript
const express = require('express');
const { createRateLimiter } = require('./sliding-window-rate-limiter');

const app = express();

// If you're behind a reverse proxy / load balancer (nginx, ALB, Cloudflare,
// Heroku, etc.), configure trust proxy so req.ip reflects the real client IP
// instead of the proxy's IP. Set this to the correct number of hops or a
// trusted IP/subnet list for your deployment — do NOT blindly use `true`
// in production, since that trusts the entire X-Forwarded-For chain.
app.set('trust proxy', 1);

const limiter = createRateLimiter({
  windowMs: 60000,   // 1 minute
  maxRequests: 100,  // 100 requests per client per sliding minute
});

app.use(limiter);

app.get('/', (req, res) => {
  res.json({ ok: true });
});

const server = app.listen(3000, () => {
  console.log('Listening on :3000');
});

// Graceful shutdown: stop the rate limiter's cleanup interval.
process.on('SIGTERM', () => {
  limiter.close();
  server.close();
});
```

Key implementation notes:

- **True sliding window**: on every request, timestamps older than `now - windowMs` are pruned from that client's array before counting, so the window boundary continuously moves with time rather than resetting on a fixed clock tick — this eliminates the boundary burst problem of fixed-window counters.
- **429 response**: `retryAfter` and the `Retry-After` header are computed from when the *oldest* timestamp in the current window will expire, giving clients an accurate wait time instead of a flat `windowMs`.
- **Memory management**: a `setInterval` every 60s prunes/removes stale per-IP entries; it's `unref()`'d and exposed via `close()` so it won't block process exit and can be torn down in tests or on graceful shutdown.
- **Scaling caveat**: this in-memory `Map` is per-process — for multi-instance deployments you'd want a shared store (e.g. Redis with sorted sets) instead.

